  S.hexPlate = (x, y, w, h, label, { kind = 'gr', field = '#00845a', fg = '#fff', font = TS.fonts.DIN, weight = 500, cap = 0.5, capEm = 0.7 } = {}) => {
    const p = HEX[kind], sx = w / p.W, sy = h / p.H, col = { fg, field };
    return p.rects.map(([rx0, ry0, rw, rh, rr, c]) => `<rect x="${r2(x + rx0 * sx)}" y="${r2(y + ry0 * sy)}" width="${r2(w - (p.W - rw) * sx)}" height="${r2(rh * sy)}" rx="${r2(rr * sy)}" fill="${col[c]}"/>`).join('') +
      `<path transform="translate(${r2(x)},${r2(y)}) scale(${+sx.toFixed(5)},${+sy.toFixed(5)})" d="${p.d}" fill="${field}"/>` +
      T(x + w / 2, y + h / 2 + cap * h / 2, String(label), cap * h / capEm, font, { fill: fg, weight, maxw: (p.fx[1] - p.fx[0]) * sx * 0.8, max: cap * h / capEm });
  };
  // the plate width for a label at height h: the drawing's own proportions up to two characters, wider after
  S.hexPlate.width = (h, label, kind = 'gr') => h * HEX[kind].W / HEX[kind].H * Math.max(1, String(label).length / 2.4);

  // ---- round 2 (2026-10-25): shields drawn from Commons files, each a set of layers in its own box ----
  // lay: the layers of a shield (d, colour) scaled to height h at x, y; num: its number in the country font, centred on
  // the drawing's own number box (cx, baseline, cap height, widest) so that it stands where the drawing's figures stand;
  // a layer [d, colour, strokeWidth, evenodd]: stroked when strokeWidth is set, filled even-odd when the file's path is
  const lay = (x, y, h, H, layers) => g(x, y, h / H, layers.map(([d, c, sw, eo]) => sw ? `<path d="${d}" fill="none" stroke="${c}" stroke-width="${sw}"/>` : `<path d="${d}" fill="${c}"${eo ? ' fill-rule="evenodd"' : ''}/>`).join(''));
  const num = (x, y, h, H, [cx, base, cap, maxw], n, o) => { const k = h / H, size = cap * k / (o.capEm || 0.72);
    return T(x + cx * k, y + base * k, String(n), size, o.font || TS.fonts.DIN, { fill: o.ink, weight: o.weight || 'normal', maxw: maxw * k, max: size }); };

