  // Hungary: the five-sided road number plate (main roads green, motorways blue): edge, white rim, field. From Commons
  // "338 (Hu) Otszogletu zold tabla.svg" (public domain, by Rl91), https://commons.wikimedia.org/wiki/File:338_(Hu)_Otszogletu_zold_tabla.svg ;
  // the motorway plate "M3 (Hu) Otszogletu kek tabla.svg" (public domain, by Joliet Jake) has the same outline. Box 208 x 152.1.
  // As on GeoHints direction-signs 145.
  const HU_P = ["M104,0L0,0L0,106.7C1.2,118.2 8.9,128.1 19.9,131.9L104,152.1L188.1,131.9C199.1,128.1 206.8,118.2 208,106.7L208,0L104,0Z","M104,4L4,4L4,103.5C4,115.5 12.2,126 23.9,128.8L104,148L184.1,128.8C195.8,126 204,115.5 204,103.5L204,4L104,4Z","M104,14L14,14L14,103.5C13.7,110.3 17.7,116.5 23.9,119.1L104,137.7L181.7,119.1C188.9,117.3 194,110.9 194,103.5L194,14L104,14Z"];
  S.huPlate = (x, y, h, n, { field = '#008000', edge = field, fg = '#fff', font, weight = 600, capEm } = {}) =>
    lay(x, y, h, 152.11, [[HU_P[0], edge], [HU_P[1], fg], [HU_P[2], field]]) + num(x, y, h, 152.11, [104, 107.4, 77, 168], n, { ink: fg, font, weight, capEm });
  S.huPlate.width = (h) => h * 208 / 152.11;

  // Hungary: the E-road plate (white plate, green rounded field, white letters). From Commons "E579-HUN.svg" (public domain,
  // by Fredddie), https://commons.wikimedia.org/wiki/File:E579-HUN.svg : box 191.8 x 111.8, rims 7 and corner radii 18 / 11
  // kept at the plate's height when the plate is narrower (the photo's E579 plate is 1.35 times as wide as high).
  S.huE = (x, y, h, label, { w = h * 191.8 / 111.8, field = '#008000', fg = '#fff', font, weight = 600, capEm } = {}) => {
    const k = h / 111.8, i = 7 * k;
    return `<rect x="${r2(x)}" y="${r2(y)}" width="${r2(w)}" height="${r2(h)}" rx="${r2(18 * k)}" fill="${fg}"/>` +
      `<rect x="${r2(x + i)}" y="${r2(y + i)}" width="${r2(w - 2 * i)}" height="${r2(h - 2 * i)}" rx="${r2(11 * k)}" fill="${field}"/>` +
      T(x + w / 2, y + 83 * k, String(label), 54.5 * k / (capEm || 0.72), font || TS.fonts.DIN, { fill: fg, weight, maxw: w - 2 * i - 10 * k, max: 54.5 * k / (capEm || 0.72) });
  };
  S.huE.width = (h) => h * 191.8 / 111.8;

  // North Macedonia: the route number plate, green for motorways, blue for the other A roads, a white rim set in from
  // the edge, white letters. From Commons "M1-MKD.svg" and "M2-MKD.svg" (public domain, by Rl91),
  // https://commons.wikimedia.org/wiki/File:M1-MKD.svg : box 224.9 x 109.5, corner radius 7.6, rim 4 wide centred 5 in,
  // its corners 8; redrawn at the plate's size (a longer label takes a wider plate). As on direction-signs 177.
  S.mkRoute = (x, y, h, label, { kind = 'motorway', w, fg = '#fff', font, weight = 600, capEm } = {}) => {
    const k = h / 109.5, W = w || Math.max(h * 1.6, h * (0.5 + 0.42 * String(label).length)), fill = kind === 'motorway' ? '#009933' : '#0066cc';
    return `<rect x="${r2(x)}" y="${r2(y)}" width="${r2(W)}" height="${r2(h)}" rx="${r2(7.6 * k)}" fill="${fill}"/>` +
      `<rect x="${r2(x + 5 * k)}" y="${r2(y + 5 * k)}" width="${r2(W - 10 * k)}" height="${r2(h - 10 * k)}" rx="${r2(8 * k)}" fill="none" stroke="${fg}" stroke-width="${r2(4 * k)}"/>` +
      T(x + W / 2, y + 89.7 * k, String(label), 70.6 * k / (capEm || 0.72), font || TS.fonts.DIN, { fill: fg, weight, maxw: W - 30 * k, max: 70.6 * k / (capEm || 0.72) });
  };
  S.mkRoute.width = (h, label) => Math.max(h * 1.6, h * (0.5 + 0.42 * String(label).length));

